		/** 
		 * Tests creating a new Person.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Person");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Person" );

			try {            
				Person entity = PersonService.getPersonInstance().createPerson( generateNewEntity() );
				thePrimaryKey = entity.getPersonId();
				LOGGER.info( "-- Successfully created a Person with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Person. 
		 */
		public Person testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Person" );

			Person entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Person with primary key" );
			msg.append( thePrimaryKey );
			
			PersonFetchOneSummary fetchOneSummary = new PersonFetchOneSummary( thePrimaryKey );

			try {
				entity = PersonService.getPersonInstance().getPerson( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Person " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Person.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Person." );

			StringBuilder msg = new StringBuilder( "Failed to update a Person : " );        
			Person entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Person." );

				// for use later on...
				thePrimaryKey = entity.getPersonId();

				PersonService proxy = PersonService.getPersonInstance();            
				proxy.updatePerson( entity );   

				LOGGER.info( "-- Successfully saved Person - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Person.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Person." );

			try{
			    Person entity = testRead(); 
				PersonService.getPersonInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Person with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Person with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Persons.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Persons:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Person : " );        
			List<Person> collection  = null;

			try {
				// call the static get method on the PersonService
				collection = PersonService.getPersonInstance().getAllPerson();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Person entity = null;            
					Iterator<Person> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getPersonId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/**
		 * Assigns a common log handler for each test class in the suite
		 * @param		handler	Handler
		 * @return		PersonTest
		 */
		public PersonTest setHandler(Handler handler) {
			this.handler = handler;
			LOGGER.addHandler(handler); // assign so the LOGGER can only output results to the Handler
			return this;
		}

		/**
		 * Returns a new populated Person
		 * 
		 * @return Person
		 */
		protected Person generateNewEntity() {
			Person entity = new Person( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  new EmailAddress(),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  new HashSet<>(),  new HashSet<>(),  new HashSet<>() );
			
			return( entity );
		}

